// Type surface for the autogenerated HyperDB spec (index.js). The spec is an
// opaque definition handed to HyperDB; only its top-level shape is described.
declare const definition: {
  versions: { schema: number; db: number }
  collections: unknown[]
  indexes: unknown[]
  resolveCollection(name: string): unknown
  resolveIndex(name: string): unknown
}

export = definition
